class Solution { public:int minimumTime(vector<vector<int>>& grid){int rows=grid.size(),cols=grid[0].size();if(rows==1&&cols==1)return 0;bool canLeave=(rows>1&&grid[1][0]<=1)||(cols>1&&grid[0][1]<=1);if(!canLeave)return -1;vector<vector<int>> distance(rows,vector<int>(cols,INT_MAX));priority_queue<array<int,3>,vector<array<int,3>>,greater<array<int,3>>> queue;distance[0][0]=0;queue.push({0,0,0});int directions[5]={-1,0,1,0,-1};while(!queue.empty()){auto [time,row,col]=queue.top();queue.pop();if(time!=distance[row][col])continue;if(row==rows-1&&col==cols-1)return time;for(int d=0;d<4;++d){int nextRow=row+directions[d],nextCol=col+directions[d+1];if(nextRow<0||nextRow>=rows||nextCol<0||nextCol>=cols)continue;int nextTime=time+1,required=grid[nextRow][nextCol];if(nextTime<required)nextTime=required+((required-nextTime)&1);if(nextTime<distance[nextRow][nextCol]){distance[nextRow][nextCol]=nextTime;queue.push({nextTime,nextRow,nextCol});}}}return -1;} };
